with cleaned as (select id, store_id, product_id, quantity, last_restock, date_sub(last_restock, 85) as last_restock_minus_85d, last_day(last_restock) as last_restock_month_end from inventory where quantity > 208) select id, product_id, quantity, lag(quantity) over w_grp as prev_quantity, row_number() over w_grp as row_seq from cleaned window w_grp as (partition by store_id order by last_restock_minus_85d asc, id asc)
